/* ============================================================
   DOI_DEPT_COST  ←  202608 엑셀 재적재 (2차 확정본)
   DB   : 도우제조원가시스템 (10.100.40.17,14233)
   원천 : 08월 계정별비용조회(260911) 2차.xlsx / 시트 '코스트센터' R4~R655 (R3 TOTAL 제외)
   행수 : 652행 / 차변합 17,625,503,863 / 대변합 18,809,570,913 / 집계제외 57행
   ★ 현재 운영 DB 는 API 원천(570행, 재배부 전)이라 카세트 배부가 붕괴됨.
     이 스크립트로 재배부 확정본(제조공통/판매공통/카세트양산배부공통 포함)으로 교체한다.
   ★ '집계 제외'열의 '제외' -> 제외여부='집계제외'
   실행 : 검증 통과 시 자동 COMMIT, 실패 시 자동 ROLLBACK
   생성 : 2026-09-11 (기존 02_DOI_DEPT_COST.sql 대체)
   ============================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @before INT = (SELECT COUNT(*) FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL');
DELETE FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL';



-- ===== 검증 =====
DECLARE @cnt INT      = (SELECT COUNT(*)                     FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL');
DECLARE @dr  BIGINT   = (SELECT SUM(CAST([차변금액] AS BIGINT)) FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL');
DECLARE @cr  BIGINT   = (SELECT SUM(CAST([대변금액] AS BIGINT)) FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL');
DECLARE @ex  INT      = (SELECT COUNT(*)                     FROM [DOI_DEPT_COST] WHERE [yyyymm]='202608' AND [site]='HQ' AND [sel_code]='ACTUAL' AND [제외여부]=N'집계제외');

PRINT '이전 행수=' + CAST(@before AS VARCHAR) + ' / 적재 행수=' + CAST(@cnt AS VARCHAR)
    + ' / 차변합=' + CAST(@dr AS VARCHAR) + ' / 대변합=' + CAST(@cr AS VARCHAR) + ' / 집계제외=' + CAST(@ex AS VARCHAR);

IF @cnt = 652 AND @dr = 17625503863 AND @cr = 18809570913 AND @ex = 57
BEGIN
    COMMIT;
    PRINT '[OK] 검증 통과 — COMMIT 완료. 이후 UP_DOI_EXPEN_MATL 부터 결산 재실행 요망.';
END
ELSE
BEGIN
    ROLLBACK;
    RAISERROR('[FAIL] 검증 실패 — ROLLBACK. 기대 행수=652 차변=17625503863 대변=18809570913 집계제외=57', 16, 1);
END
